# Generated by sila2.code_generator; sila2.__version__: 0.14.0, then implemented by hand.
"""Simulated heating block A: first-order approach to the target, updated every 100 ms.

Simulation faults come from the JSON file named by SIM_FAULT_FILE (written by the
experiment harness, read once per command):
  {"next_set": "apply_then_delay", "delay_s": 8}  the next SetTargetTemperature applies,
                                                  then answers only after the delay
  {"heater_fault": true}                          the heater faults until ResetHeater
"""

from __future__ import annotations

import json
import os
import threading
import time
from typing import TYPE_CHECKING

from sila2.server import MetadataDict

from ..generated.temperaturecontroller import (
    HeaterFault,
    ResetHeater_Responses,
    SetTargetTemperature_Responses,
    ShutDown_Responses,
    TemperatureControllerBase,
)

if TYPE_CHECKING:
    from ..server import Server

AMBIENT_C = 22.0
TIME_CONSTANT_S = 2.0


class TemperatureControllerImpl(TemperatureControllerBase):
    def __init__(self, parent_server: Server) -> None:
        super().__init__(parent_server=parent_server)
        self.target = AMBIENT_C
        self.current = AMBIENT_C
        self.faulted = False
        self.on = True
        self.sets = 0  # the simulator's own count of applied targets
        self.lock = threading.Lock()
        self.update_CurrentTemperature(self.current)
        self.run_periodically(self._step, delay_seconds=0.1)

    def _step(self) -> None:
        with self.lock:
            goal = self.target if self.on else AMBIENT_C
            self.current += (goal - self.current) * (0.1 / TIME_CONSTANT_S)
            value = round(self.current, 3)
        self.update_CurrentTemperature(value)

    def _fault(self) -> dict:
        path = os.environ.get("SIM_FAULT_FILE")
        if not path or not os.path.exists(path):
            return {}
        with open(path, encoding="utf-8") as f:
            fault = json.load(f)
        os.remove(path)
        return fault

    def get_TargetTemperature(self, *, metadata: MetadataDict) -> float:
        return self.target

    def get_HeaterFaulted(self, *, metadata: MetadataDict) -> bool:
        return self.faulted

    def SetTargetTemperature(self, TargetTemperature: float, *, metadata: MetadataDict) -> SetTargetTemperature_Responses:
        fault = self._fault()
        if fault.get("heater_fault"):
            self.faulted = True
        if self.faulted:
            raise HeaterFault("heater A is faulted; reset it first")
        with self.lock:
            self.target = TargetTemperature
            self.on = True
            self.sets += 1
        if fault.get("next_set") == "apply_then_delay":
            time.sleep(float(fault.get("delay_s", 8)))
        return SetTargetTemperature_Responses()

    def ResetHeater(self, *, metadata: MetadataDict) -> ResetHeater_Responses:
        self.faulted = False
        return ResetHeater_Responses()

    def ShutDown(self, *, metadata: MetadataDict) -> ShutDown_Responses:
        with self.lock:
            self.on = False
        return ShutDown_Responses()
